/*
 * Fisher (FQP) crib pricing, add-ons and delivery, end to end through the
 * server pricer that bills the invoice (src/lib/pricing.ts) and the browser
 * resolver that the cart and checkout summary display (src/lib/cart-pricing.ts).
 *
 * Run with `npm test` (builds the catalogue first: data/pricing.json and
 * public/data/inventory.json are generated by scripts/build-data.mjs).
 *
 * Source of the numbers: the pricing app's suggested prices, 2026-10-20 -
 * crib only / crib + 4-in-1 conversion package. The package is the crib plus
 * the toddler kit and the full rails, a $500 add-on, sold as $250 + $250 so
 * crib + both kits is exactly the package.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { priceCart, cartSubtotalCents } from '../src/lib/pricing';
import { chargedSubtotalCents, chargedUnitPrices, type PricedCartLineInput } from '../src/lib/cart-pricing';
import { SHIPPING_METHODS, shippingCentsFor, cheapestShippingCents } from '../src/lib/order-terms';

const FISHER: ReadonlyArray<{ name: string; sku: string; crib: number; pkg: number }> = [
  { name: 'Arched Top', sku: 'FQP-201', crib: 2050, pkg: 2550 },
  { name: 'Bloomington', sku: 'FQP-601', crib: 2200, pkg: 2700 },
  { name: 'Darlington', sku: 'FQP-501', crib: 2000, pkg: 2500 },
  { name: 'Hudson', sku: 'FQP-301', crib: 1950, pkg: 2450 },
  { name: 'Mission', sku: 'FQP-101', crib: 2000, pkg: 2500 },
  { name: 'Moyerton', sku: 'FQP-701', crib: 2300, pkg: 2800 },
  { name: 'Princeton', sku: 'FQP-401', crib: 2050, pkg: 2550 },
];
const TODDLER = 'Toddler Bed Rail Kit'; // public/data/products/Toddler Conversion Rail
const RAILS = 'Full Bed Rail Kit';
const ADDON = 250;
const TODDLER_LIST = 109;
const RAILS_LIST = 481;

interface PricingRow {
  productName: string;
  wood: string;
  basePrice: number;
  bundleOverrides?: Array<{ productName: string; wood: string; stainName: string; price: number }>;
  stains: Array<{ name: string; inStock: boolean }>;
}
interface InventoryRow {
  productName: string;
  wood: string;
  basePrice: number;
  bundle?: Array<{ productName: string; price: number; listPrice?: number; bundleOverride?: boolean }>;
}

const pricing = JSON.parse(readFileSync(new URL('../data/pricing.json', import.meta.url), 'utf8')) as PricingRow[];
const inventory = JSON.parse(
  readFileSync(new URL('../public/data/inventory.json', import.meta.url), 'utf8')
) as InventoryRow[];

const rowsFor = (name: string) => pricing.filter(r => r.productName === name);
const override = (row: PricingRow, kit: string) => {
  const o = row.bundleOverrides?.find(b => b.productName === kit);
  assert.ok(o, `${row.productName} / ${row.wood} has no bundle price for ${kit}`);
  return o;
};
const cents = (dollars: number) => Math.round(dollars * 100);

type Line = { productName: string; wood: string; stainName: string; quantity?: number; bundledWith?: { productName: string; wood: string } };

function cribLine(row: PricingRow, quantity = 1): Line {
  const stain = row.stains.find(s => s.inStock);
  assert.ok(stain, `${row.productName} / ${row.wood} has no in-stock finish`);
  return { productName: row.productName, wood: row.wood, stainName: stain.name, quantity };
}
function kitLine(row: PricingRow, kit: string, quantity = 1): Line {
  const o = override(row, kit);
  return {
    productName: o.productName,
    wood: o.wood,
    stainName: o.stainName,
    quantity,
    bundledWith: { productName: row.productName, wood: row.wood },
  };
}
/* What the cart stores for the same lines: price as shown in the picker. */
function asCart(row: PricingRow, lines: Line[]): PricedCartLineInput[] {
  return lines.map(l => {
    if (l.productName === row.productName) {
      return { productName: l.productName, wood: l.wood, quantity: l.quantity ?? 1, price: row.basePrice };
    }
    const list = l.productName === TODDLER ? TODDLER_LIST : RAILS_LIST;
    return {
      productName: l.productName,
      wood: l.wood,
      quantity: l.quantity ?? 1,
      price: l.bundledWith ? ADDON : list,
      ...(l.bundledWith ? { listPrice: list, bundledWith: l.bundledWith } : {}),
    };
  });
}

test('delivery: exactly two tiers, curbside $175 and white glove $225', () => {
  assert.deepEqual(
    SHIPPING_METHODS.map(m => [m.id, m.name, m.cents]),
    [
      ['threshold', 'Curbside Delivery', 17_500],
      ['white_glove', 'White Glove Delivery', 22_500],
    ]
  );
  assert.equal(shippingCentsFor('threshold'), 17_500);
  assert.equal(shippingCentsFor('white_glove'), 22_500);
  assert.equal(cheapestShippingCents(), 17_500);
});

test('standalone kit prices are unchanged ($109 toddler kit, $481 full rails)', () => {
  const toddler = rowsFor(TODDLER)[0];
  const rails = rowsFor(RAILS)[0];
  assert.equal(toddler.basePrice, TODDLER_LIST);
  assert.equal(rails.basePrice, RAILS_LIST);
  assert.equal(
    cartSubtotalCents([{ productName: TODDLER, wood: toddler.wood, stainName: toddler.stains[0].name }]),
    cents(TODDLER_LIST)
  );
});

for (const p of FISHER) {
  test(`${p.name} (${p.sku}): crib, each kit, both kits = package, plus delivery`, () => {
    const rows = rowsFor(p.name);
    assert.ok(rows.length > 0, `${p.name} missing from data/pricing.json`);
    assert.equal(p.pkg - p.crib, 2 * ADDON, 'source data: package = crib + $500');

    for (const row of rows) {
      const where = `${p.name} / ${row.wood}`;
      assert.equal(row.basePrice, p.crib, `${where} crib price`);
      assert.equal(override(row, TODDLER).price, ADDON, `${where} toddler kit add-on`);
      assert.equal(override(row, RAILS).price, ADDON, `${where} full rails add-on`);

      const combos: Array<[string, Line[], number]> = [
        ['crib only', [cribLine(row)], p.crib],
        ['crib + toddler kit', [cribLine(row), kitLine(row, TODDLER)], p.crib + ADDON],
        ['crib + full rails', [cribLine(row), kitLine(row, RAILS)], p.crib + ADDON],
        ['crib + both = package', [cribLine(row), kitLine(row, TODDLER), kitLine(row, RAILS)], p.pkg],
      ];
      for (const [label, lines, expected] of combos) {
        // What the invoice charges...
        assert.equal(cartSubtotalCents(lines), cents(expected), `${where} ${label} (server)`);
        // ...and what the cart / checkout summary shows, line by line.
        assert.equal(chargedSubtotalCents(asCart(row, lines)), cents(expected), `${where} ${label} (cart)`);
      }

      // Cart total with each delivery tier (NJ: no sales tax).
      const both = [cribLine(row), kitLine(row, TODDLER), kitLine(row, RAILS)];
      const curb = priceCart(both, 'NJ', 'threshold');
      assert.equal(curb.subtotalCents, cents(p.pkg));
      assert.equal(curb.shippingCents, 17_500);
      assert.equal(curb.taxCents, 0);
      assert.equal(curb.totalCents, cents(p.pkg + 175), `${where} package + curbside`);
      const glove = priceCart(both, 'NJ', 'white_glove');
      assert.equal(glove.shippingCents, 22_500);
      assert.equal(glove.totalCents, cents(p.pkg + 225), `${where} package + white glove`);
      // PA: 6% on goods plus delivery.
      const pa = priceCart(both, 'PA', 'threshold');
      assert.equal(pa.taxCents, Math.round((cents(p.pkg + 175) * 600) / 10_000));
      assert.equal(pa.totalCents, cents(p.pkg + 175) + pa.taxCents);
      // Crib alone with each tier.
      assert.equal(priceCart([cribLine(row)], 'NJ', 'threshold').totalCents, cents(p.crib + 175));
      assert.equal(priceCart([cribLine(row)], 'NJ', 'white_glove').totalCents, cents(p.crib + 225));
    }

    // The product page picker reads its prices from inventory.json.
    for (const inv of inventory.filter(i => i.productName === p.name)) {
      assert.equal(inv.basePrice, p.crib, `${p.name} / ${inv.wood} page price`);
      const t = inv.bundle?.find(b => b.productName === TODDLER);
      const r = inv.bundle?.find(b => b.productName === RAILS);
      assert.deepEqual([t?.price, t?.listPrice, t?.bundleOverride], [ADDON, TODDLER_LIST, true]);
      assert.deepEqual([r?.price, r?.listPrice, r?.bundleOverride], [ADDON, RAILS_LIST, true]);
    }
  });
}

test('cart and invoice agree when the add-on price does NOT apply', () => {
  const row = rowsFor('Mission')[0];
  const scenarios: Array<[string, Line[]]> = [
    // The crib was removed, the kits stayed: both charged their own price.
    ['kits without their crib', [kitLine(row, TODDLER), kitLine(row, RAILS)]],
    // Two toddler kits against one crib: the line falls back, all or nothing.
    ['more kits than cribs', [cribLine(row), kitLine(row, TODDLER, 2), kitLine(row, RAILS)]],
    // Two cribs, two of each kit: every unit at the add-on price.
    ['two cribs, two of each kit', [cribLine(row, 2), kitLine(row, TODDLER, 2), kitLine(row, RAILS, 2)]],
  ];
  const expected = [
    cents(TODDLER_LIST + RAILS_LIST),
    cents(2000 + 2 * TODDLER_LIST + ADDON),
    cents(2 * 2000 + 4 * ADDON),
  ];
  scenarios.forEach(([label, lines], i) => {
    assert.equal(cartSubtotalCents(lines), expected[i], `${label} (server)`);
    assert.equal(chargedSubtotalCents(asCart(row, lines)), expected[i], `${label} (cart)`);
  });
  assert.deepEqual(chargedUnitPrices(asCart(row, scenarios[0][1])), [TODDLER_LIST, RAILS_LIST]);
});
